using System;
using System.Collections.Generic;
using System.IO;
using System.Text;

namespace EditableEncyclopedia
{
    /// <summary>
    /// Manages localization for all user-facing runtime strings.
    /// Language files are JSON stored in the Languages subfolder of the config directory.
    /// Falls back to English defaults if a key is missing or no language file is loaded.
    ///
    /// Note: MCM setting labels/hints are set via compile-time attributes and remain in English.
    /// Only runtime strings (popups, messages, hints) are localized.
    /// </summary>
    public static class Localization
    {
        // All four fields are volatile so concurrent L() + SetLanguage() callers see
        // a consistent reference. Volatile guards the REFERENCE swap, not internal
        // dictionary mutations — those still require a lock if/when added later.
        // Round 3 finding LZW-1.
        private static volatile Dictionary<string, string> _strings = new Dictionary<string, string>();
        private static volatile Dictionary<string, string> _fallback = new Dictionary<string, string>();
        private static volatile string _currentLanguage = "en";
        private static volatile bool _initialized = false;

        private static readonly string LanguagesFolder = Path.Combine(
            Environment.GetFolderPath(Environment.SpecialFolder.MyDocuments),
            "Mount and Blade II Bannerlord",
            "Configs", "ModSettings", "Global", "EditableEncyclopedia", "Languages");

        /// <summary>
        /// Initializes the localization system. Generates default language files if they
        /// don't exist, then loads the configured language.
        /// </summary>
        public static void Initialize(string languageCode = null)
        {
            if (string.IsNullOrWhiteSpace(languageCode))
                languageCode = "en";

            _currentLanguage = languageCode.Trim().ToLowerInvariant();
            _fallback = GetEnglishDefaults();

            // Ensure Languages folder exists and default files are generated
            try
            {
                if (!Directory.Exists(LanguagesFolder))
                    Directory.CreateDirectory(LanguagesFolder);

                GenerateDefaultFiles();
            }
            catch (Exception ex) { EECoreLogger.For("EE-Core").Debug("[Localization]: " + ex.ToString()); }

            // Load the selected language from disk (if a file exists)
            _strings = LoadLanguageFile(_currentLanguage);

            // Merge any keys that exist in the in-code defaults for this language
            // but NOT on disk. This covers the case where the user has an old JSON
            // file from a previous mod version and we've since added new keys.
            // Disk values win FOR USER-EDITABLE KEYS (popup/message text) — user edits are preserved.
            // EXCEPTION: mcm_* keys (MCM UI labels) always take the in-code value, because
            // older on-disk files contain legacy cross-language contamination (e.g., an en.json
            // with Ukrainian MCM strings carried over from a buggy earlier dict). Users should
            // not be customizing mcm_* keys via JSON anyway — those are compile-time attribute
            // labels whose per-language defaults live in GetXxxDefaults().
            try
            {
                var codeDefaults = GetDefaultsFor(_currentLanguage);
                int added = 0, overwritten = 0;
                foreach (var kvp in codeDefaults)
                {
                    bool isMcmKey = kvp.Key.StartsWith("mcm_");
                    if (isMcmKey)
                    {
                        if (!_strings.TryGetValue(kvp.Key, out var existing))
                        {
                            _strings[kvp.Key] = kvp.Value;
                            added++;
                        }
                        else if (existing != kvp.Value)
                        {
                            _strings[kvp.Key] = kvp.Value;
                            overwritten++;
                        }
                    }
                    else if (!_strings.ContainsKey(kvp.Key))
                    {
                        _strings[kvp.Key] = kvp.Value;
                        added++;
                    }
                }
                if (added > 0 || overwritten > 0)
                    EECoreLogger.For("EE-Core").Debug($"[Localization] Merge: added {added} missing keys, overwrote {overwritten} mcm_* keys (healing legacy contamination) for {_currentLanguage}");
            }
            catch (Exception ex) { EECoreLogger.For("EE-Core").Debug("[Localization] Merge error: " + ex.ToString()); }

            _initialized = true;

            // Diagnostic: if a non-English language was requested but no strings
            // actually loaded, this is the "language won't change" user bug.
            if (_currentLanguage != "en" && _strings.Count == 0)
            {
                EECoreLogger.For("EE-Core").Debug($"[Localization] WARNING: language '{_currentLanguage}' requested but 0 strings loaded. " +
                    $"Expected file: {Path.Combine(LanguagesFolder, _currentLanguage + ".json")}. " +
                    $"Falling back to English. Available files in folder: {ListAvailableFiles()}");
            }
            else
            {
                EECoreLogger.For("EE-Core").Debug($"Localization initialized: language={_currentLanguage}, keys={_strings.Count}");
            }
        }

        /// <summary>
        /// Lists .json files currently in the Languages folder for diagnostic output.
        /// </summary>
        private static string ListAvailableFiles()
        {
            try
            {
                if (!Directory.Exists(LanguagesFolder)) return "(folder missing)";
                var files = Directory.GetFiles(LanguagesFolder, "*.json");
                if (files.Length == 0) return "(none)";
                var names = new List<string>();
                foreach (var f in files) names.Add(Path.GetFileNameWithoutExtension(f));
                return string.Join(", ", names);
            }
            catch { return "(error listing)"; }
        }

        /// <summary>
        /// Gets a localized string by key. Returns the English fallback if the key is
        /// not found in the current language. Returns the key itself if not found at all.
        /// </summary>
        public static string L(string key)
        {
            if (!_initialized) Initialize();

            if (_strings.TryGetValue(key, out string value))
                return value;
            if (_fallback.TryGetValue(key, out string fallback))
                return fallback;
            return key;
        }

        /// <summary>
        /// Gets a localized string by key with string.Format parameters.
        /// </summary>
        public static string L(string key, params object[] args)
        {
            string template = L(key);
            try
            {
                return string.Format(template, args);
            }
            catch (Exception ex)
            {
                EECoreLogger.For("EE-Core").Debug("[Localization]: " + ex.ToString());
                return template;
            }
        }

        /// <summary>
        /// Reloads the localization with a new language code.
        /// </summary>
        public static void SetLanguage(string languageCode)
        {
            Initialize(languageCode);
        }

        /// <summary>
        /// Returns the currently loaded language code (e.g., "en", "tr").
        /// </summary>
        public static string GetCurrentLanguage() => _currentLanguage;

        /// <summary>
        /// Returns true if Localization.Initialize has been called at least once.
        /// </summary>
        public static bool IsInitialized() => _initialized;

        /// <summary>
        /// Returns a list of available language codes by scanning the Languages folder.
        /// </summary>
        public static List<string> GetAvailableLanguages()
        {
            var languages = new List<string>();
            try
            {
                if (Directory.Exists(LanguagesFolder))
                {
                    foreach (var file in Directory.GetFiles(LanguagesFolder, "*.json"))
                    {
                        string name = Path.GetFileNameWithoutExtension(file);
                        if (!string.IsNullOrEmpty(name))
                            languages.Add(name);
                    }
                }
            }
            catch (Exception ex) { EECoreLogger.For("EE-Core").Debug("[Localization]: " + ex.ToString()); }

            if (languages.Count == 0)
                languages.Add("en");

            return languages;
        }

        /// <summary>
        /// Returns the path to the Languages folder so users know where to add files.
        /// </summary>
        public static string GetLanguagesFolder() => LanguagesFolder;

        // ── File I/O ──────────────────────────────────────────

        private static Dictionary<string, string> LoadLanguageFile(string langCode)
        {
            var result = new Dictionary<string, string>();
            try
            {
                string filePath = Path.Combine(LanguagesFolder, langCode + ".json");
                if (!File.Exists(filePath))
                {
                    EECoreLogger.For("EE-Core").Debug($"Language file not found: {filePath}, using English defaults");
                    return result;
                }

                string json = File.ReadAllText(filePath, Encoding.UTF8);
                result = ParseSimpleJson(json);
                EECoreLogger.For("EE-Core").Debug($"Loaded language file: {filePath} ({result.Count} keys)");
            }
            catch (Exception ex)
            {
                EECoreLogger.For("EE-Core").Debug($"Error loading language file: {ex.Message}");
            }
            return result;
        }

        private static void GenerateDefaultFiles()
        {
            // Each language is wrapped individually so one failing translation
            // dict doesn't prevent the others from being written.
            SafeGenerate("en", GetEnglishDefaults);
            SafeGenerate("tr", GetTurkishDefaults);
            SafeGenerate("de", GetGermanDefaults);
            SafeGenerate("fr", GetFrenchDefaults);
            SafeGenerate("es", GetSpanishDefaults);
            SafeGenerate("zh", GetChineseDefaults);
            SafeGenerate("ru", GetRussianDefaults);
            SafeGenerate("pt", GetPortugueseDefaults);
            SafeGenerate("ko", GetKoreanDefaults);
            SafeGenerate("ja", GetJapaneseDefaults);
            SafeGenerate("pl", GetPolishDefaults);
            SafeGenerate("uk", GetUkrainianDefaults);
        }

        private static void SafeGenerate(string langCode, Func<Dictionary<string, string>> supplier)
        {
            try { GenerateLanguageFile(langCode, supplier()); }
            catch (Exception ex) { EECoreLogger.For("EE-Core").Debug($"[Localization] Failed to generate {langCode}.json: {ex.Message}"); }
        }

        private static void GenerateLanguageFile(string langCode, Dictionary<string, string> strings)
        {
            try
            {
                string filePath = Path.Combine(LanguagesFolder, langCode + ".json");
                if (File.Exists(filePath))
                    return; // Don't overwrite existing files

                var sb = new StringBuilder();
                sb.AppendLine("{");

                bool first = true;
                foreach (var kvp in strings)
                {
                    if (!first) sb.AppendLine(",");
                    first = false;
                    sb.Append($"  \"{EscapeJson(kvp.Key)}\": \"{EscapeJson(kvp.Value)}\"");
                }

                sb.AppendLine();
                sb.AppendLine("}");

                File.WriteAllText(filePath, sb.ToString(), Encoding.UTF8);
            }
            catch (Exception ex) { EECoreLogger.For("EE-Core").Debug("[Localization]: " + ex.ToString()); }
        }

        // ── Default Strings ──────────────────────────────────

        /// <summary>
        /// Returns the in-code default dict for the given language code.
        /// Falls back to English if the language is unknown.
        /// </summary>
        private static Dictionary<string, string> GetDefaultsFor(string langCode)
        {
            switch ((langCode ?? "en").Trim().ToLowerInvariant())
            {
                case "tr": return GetTurkishDefaults();
                case "de": return GetGermanDefaults();
                case "fr": return GetFrenchDefaults();
                case "es": return GetSpanishDefaults();
                case "zh": return GetChineseDefaults();
                case "ru": return GetRussianDefaults();
                case "pt": return GetPortugueseDefaults();
                case "ko": return GetKoreanDefaults();
                case "ja": return GetJapaneseDefaults();
                case "pl": return GetPolishDefaults();
                case "uk": return GetUkrainianDefaults();
                default:   return GetEnglishDefaults();
            }
        }

