                // The Living Chronicle intro popup
                ["intro_title"] = "The Living Chronicle",
                ["intro_body"] = "Every lord has a story. Every clan carries a legacy. Every kingdom rises and falls.\n\nYou have always felt the pull of history — the need to record, to remember, to give meaning to the chaos of Calradia. Now, the encyclopedia lies open before you, waiting for your ink.\n\nPress Ctrl+E on any encyclopedia page to write descriptions and lore. Ctrl+N to rename heroes, Ctrl+B to edit banners, Ctrl+U for cultures, Ctrl+G for tags, Ctrl+J for journal entries, and Ctrl+F for relation notes.\n\n────────────────────────────\n\nIf you find any bugs, crashes, or issues — please report them directly to me. Your bug reports are what keep this mod alive. Without knowing what's broken, I can't fix it.\n\nReport via Steam Workshop comments, Nexus Bugs tab, or Discord:\ndiscord.com/users/404393620897136640\n\nThank you for using Editable Encyclopedia.\n— XMuPb",
