                // MCM settings: property hints
                ["mcm_author_hint"] = "The author of this mod.",
                ["mcm_version_hint"] = "Current version of Editable Encyclopedia.",
                ["mcm_join_discord_hint"] = "Click to open the Discord invite link (discord.com/users/404393620897136640) in your browser.",
                ["mcm_encyclopedia_edit_statistics_hint"] = "Displays a summary of all custom edits in the current campaign: descriptions, names, titles, banners, cultures, occupations, lore fields, tags, journal entries, and relation notes.",
                ["mcm_open_config_folder_hint"] = "Opens the EditableEncyclopedia config folder where your MCM JSON settings are stored.",
                ["mcm_show_edit_hint_hint"] = "Append '[Ctrl+E to Edit Description]' to encyclopedia page text.",
                ["mcm_show_name_edit_hint_hint"] = "Show '[Ctrl+N to Edit Name]' hint on hero encyclopedia pages.",
                ["mcm_show_banner_edit_hint_hint"] = "Show '[Ctrl+B to Edit Banner]' hint on encyclopedia pages.",
                ["mcm_show_culture_edit_hint_hint"] = "Show '[Ctrl+U to Edit Culture]' hint on hero encyclopedia pages.",
                ["mcm_show_occupation_edit_hint_hint"] = "Show '[Ctrl+O to Edit Occupation]' hint on hero encyclopedia pages.",
                ["mcm_show_tag_edit_hint_hint"] = "Show '[G Tags]' hint on encyclopedia pages.",
                ["mcm_show_confirmation_messages_hint"] = "Display a green message when a description is saved.",
                ["mcm_show_edited_indicator_hint"] = "Prepend '[Edited]' to encyclopedia descriptions that have been customized, making them easy to identify.",
                ["mcm_show_edit_timestamp_hint"] = "Display the in-game date when a description was last edited (e.g., 'Edited: Day 15 of Spring, 1084').",
                ["mcm_auto_export_on_save_hint"] = "Automatically export all data (descriptions, names, titles, banners, cultures, occupations, lore fields, tags, timestamps, journal entries, relation notes, tag notes, relation history, tag categories, tag presets, auto-tag thresholds) to the shared JSON file every time a save occurs. Keeps the export file always up-to-date.",
                ["mcm_auto_import_on_load_hint"] = "Automatically import all data (descriptions, names, titles, banners, cultures, occupations, lore fields, tags, timestamps, journal entries, relation notes, tag notes, relation history, tag categories, tag presets, auto-tag thresholds) from the shared JSON file when a save is loaded. Useful for keeping data synced across campaigns.",
                ["mcm_enable_hero_editing_hint"] = "Allow editing descriptions on Hero encyclopedia pages.",
                ["mcm_enable_name_editing_ctrl_n_hint"] = "Allow editing names on encyclopedia pages using Ctrl+N. Works on Hero (name + title), Clan, Kingdom, and Settlement pages.",
                ["mcm_max_name_length_hint"] = "Maximum number of characters allowed when editing names or titles via Ctrl+N. Shorter limits prevent UI overflow.",
                ["mcm_enable_clan_editing_hint"] = "Allow editing descriptions on Clan encyclopedia pages.",
                ["mcm_enable_kingdom_editing_hint"] = "Allow editing descriptions on Kingdom/Faction encyclopedia pages.",
                ["mcm_enable_settlement_editing_hint"] = "Allow editing descriptions on Settlement encyclopedia pages.",
                ["mcm_enable_banner_flag_editing_hint"] = "Allow editing banners/flags on encyclopedia pages using Ctrl+B. Paste a banner code to change the banner for Heroes, Clans, Kingdoms, or Settlements.",
                ["mcm_enable_culture_editing_hint"] = "Allow changing a hero's culture on Hero encyclopedia pages using Ctrl+U. You can select from existing cultures or create a custom one.",
                ["mcm_enable_occupation_editing_hint"] = "Allow changing a hero's occupation on Hero encyclopedia pages using Ctrl+O. Choose from available occupations like Lord, Wanderer, Merchant, etc.",
                ["mcm_enable_tag_editing_hint"] = "Allow adding player-defined tags (e.g. ally, enemy, target) to any encyclopedia entry using Ctrl+G. Tags are displayed on the page and included in exports.",
                ["mcm_tag_font_scale_hint"] = "Scales the font size of the tag display on encyclopedia pages as a percentage. 100 = normal, 130 = default (1.3x), 200 = double size.",
                ["mcm_enable_auto_tags_hint"] = "Automatically generate tags for heroes based on game state (relation, party size, clan wealth). Auto-tags appear alongside manual tags with an 'Auto:' prefix and are recalculated daily.",
                ["mcm_auto_tag_enemy_relation_hint"] = "Heroes with relation at or below this threshold get an 'Auto: Enemy' tag. Default: -30.",
                ["mcm_auto_tag_friend_relation_hint"] = "Heroes with relation at or above this threshold get an 'Auto: Friend' tag. Default: 30.",
                ["mcm_auto_tag_dangerous_party_size_hint"] = "Heroes leading parties with at least this many troops get an 'Auto: Dangerous' tag. Default: 200.",
                ["mcm_enable_journal_hint"] = "Allow adding chronicle notes (campaign diary) to any encyclopedia entry using Ctrl+J. Notes are displayed in a 'Journal' section on the page.",
                ["mcm_enable_auto_chronicle_hint"] = "Automatically log game events (battles, diplomacy, tournaments, captures, etc.) as chronicle notes on relevant encyclopedia entries.",
                ["mcm_enable_global_chronicle_panel_hint"] = "Show a 'Chronicle Notes' button on the campaign map that opens a panel with all world history events (war declarations, peace treaties, political changes, etc.).",
                ["mcm_enable_relation_notes_hint"] = "Allow writing personal notes about hero relationships using Ctrl+F. Notes appear in the Friends/Enemies section on hero encyclopedia pages.",
                ["mcm_enable_timeline_hint"] = "Show a 'Timeline' section on hero encyclopedia pages with a chronological personal biography of battles, captures, family events, and manual notes.",
                ["mcm_timeline_page_size_hint"] = "Number of timeline entries shown per page. Lower values improve performance for heroes with many events. Default: 25.",
                ["mcm_enable_lore_section_hint"] = "Show the collapsible 'Lore' section on hero encyclopedia pages displaying narrative fields (Backstory, Personality, Goals, Relationships, Rumors). Disable to hide the Lore section entirely.",
                ["mcm_enable_info_stats_hint"] = "Show the 'Info' stats panel on encyclopedia pages (Hero: Culture, Troops, Kills, Hall Rank, etc. | Clan: Renown, Troops, etc. | Kingdom: Clans, Wars, etc. | Settlement: Prosperity, Loyalty, etc.).",
                ["mcm_show_edit_popup_portrait_hint"] = "Display a hero face portrait or clan/kingdom banner emblem in the edit popup title area. Disable for a simpler popup appearance.",
                ["mcm_journal_page_size_hint"] = "Number of journal/chronicle entries shown per page on encyclopedia pages. Default: 10.",
                ["mcm_chronicle_panel_page_size_hint"] = "Number of entries shown per page in the Global Chronicle Panel on the campaign map. Default: 22.",
                ["mcm_show_journal_hint_hint"] = "Show 'J Journal' in the keyboard shortcut hint on encyclopedia pages.",
                ["mcm_show_relation_note_hint_hint"] = "Show 'F Friend Note' in the keyboard shortcut hint on hero encyclopedia pages.",
                ["mcm_prevent_kingdom_color_overwrites_hint"] = "In 1.3.13, the game's kingdom logic frequently forces banners back to default culture colors. Enable this to periodically re-apply your custom banners when the game overwrites them.",
                ["mcm_create_custom_banner_hint"] = "Opens bannerlord.party/banner in your browser where you can design a custom banner and copy its code. Then use Ctrl+B in the encyclopedia to paste it.",
                ["mcm_manage_custom_cultures_hint"] = "View and delete custom culture assignments. Shows a list of heroes with custom cultures — click to delete and restore to original.",
                ["mcm_manage_custom_occupations_hint"] = "View and delete custom occupation assignments. Shows a list of heroes with custom occupations — click to delete and restore to original.",
                ["mcm_manage_tags_hint"] = "View, rename, and delete tags across all encyclopedia entries. Allows bulk tag management from the settings menu.",
                ["mcm_filter_by_tag_hint"] = "Search for all encyclopedia entries that have a specific tag. Shows matching heroes, clans, kingdoms, and settlements.",
                ["mcm_manage_tag_presets_hint"] = "Save and load tag presets (templates). A preset is a named collection of tags that can be quickly applied to any encyclopedia entry.",
                ["mcm_manage_tag_categories_hint"] = "Create and manage custom tag categories. Categories group tags in the Quick Tag Menu and tag display.",
                ["mcm_export_all_to_json_hint"] = "Exports all custom data (descriptions, names, titles, banners, cultures, occupations, lore fields, tags, timestamps, journal entries, relation notes, tag notes, relation history, tag categories, tag presets, auto-tag thresholds) to a JSON v10 file that can be shared or imported into another campaign.",
                ["mcm_import_all_from_json_hint"] = "Imports all data (descriptions, names, titles, banners, cultures, occupations) from the JSON file on disk and merges into the current campaign. Existing entries are overwritten.",
                ["mcm_export_heroes_only_hint"] = "Exports only Hero descriptions to the shared JSON file.",
                ["mcm_export_clans_only_hint"] = "Exports only Clan descriptions to the shared JSON file.",
                ["mcm_export_kingdoms_only_hint"] = "Exports only Kingdom descriptions to the shared JSON file.",
                ["mcm_export_settlements_only_hint"] = "Exports only Settlement descriptions to the shared JSON file.",
                ["mcm_export_banners_only_hint"] = "Exports only custom banner codes to the shared JSON file.",
                ["mcm_import_banners_only_hint"] = "Imports only custom banner codes from the shared JSON file into the current campaign.",
                ["mcm_reset_all_descriptions_hint"] = "Removes ALL custom descriptions from the current campaign. This cannot be undone!",
                ["mcm_initial_key_poll_delay_ms_hint"] = "Delay in milliseconds before the Ctrl+E key poller starts after opening an encyclopedia page. Prevents accidental triggers.",
                ["mcm_key_poll_interval_ms_hint"] = "How often (in milliseconds) the mod checks for the Ctrl+E key press. Lower = more responsive, higher = less CPU usage.",
                ["mcm_max_description_length_hint"] = "Maximum characters for the main Description field. Set to 0 for unlimited.",
                ["mcm_max_narrative_field_length_hint"] = "Maximum characters for narrative fields (Backstory, Rumors/Secrets). Set to 0 for unlimited.",
                ["mcm_max_stats_field_length_hint"] = "Maximum characters for short stats fields (Personality, Goals, Relationships). Set to 0 for unlimited.",
                ["mcm_language_hint"] = "Language for popups, messages, and runtime strings. Applies live — no restart needed. Note: MCM labels themselves stay in English (they are compile-time). Language files: Documents/Mount and Blade II Bannerlord/Configs/ModSettings/Global/EditableEncyclopedia/Languages/.",
                ["mcm_debug_mode_hint"] = "Enable verbose logging to the debug.log file (in the EditableEncyclopedia config folder). Does not show messages on screen unless 'Show Debug On Screen' is also enabled.",
                ["mcm_show_debug_on_screen_hint"] = "When Debug Mode is enabled, also display debug messages as yellow in-game text. Warning: this is very verbose and may clutter the screen, especially on encyclopedia pages.",
                ["mcm_enable_web_extension_eewebextension_hint"] = "Enable the EE Web Extension mod. When enabled and the EEWebExtension module is installed, a local web server runs on http://127.0.0.1:8080/ allowing you to browse and edit encyclopedia data from your browser. Disable to prevent the web server from starting. Requires game restart to take effect.",
                ["mcm_web_extension_status_hint"] = "Shows whether the EE Web Extension module is currently loaded and running.",
                ["mcm_web_server_port_hint"] = "The port number for the web server. Default is 8080 (http://127.0.0.1:8080). Change if another app uses port 8080. Requires restart.",
                ["mcm_auto_open_browser_hint"] = "Automatically open the web encyclopedia in your default browser when a campaign is loaded.",
                ["mcm_allow_external_access_hint"] = "Allow connections from other devices on your local network (e.g. phone, tablet). When OFF, only this PC can access the web encyclopedia. When ON, any device on your network can connect via your PC's IP address. Requires restart.",
                ["mcm_enable_editing_from_web_hint"] = "Allow editing encyclopedia entries (descriptions, names, tags, etc.) from the web interface. When OFF, the web interface is read-only.",
                ["mcm_enable_portrait_extraction_hint"] = "Allow the web extension to extract hero portraits from the game for display in the web interface.",
                ["mcm_live_sync_interval_seconds_hint"] = "How often the web detail views auto-refresh with live game data. Lower = more responsive but more CPU. Default is 8 seconds.",
                ["mcm_live_sync_on_detail_views_hint"] = "Automatically refresh detail views (Hero, Clan, Settlement, Kingdom) with live game data. Shows a LIVE badge when active.",
                ["mcm_live_chronicle_updates_hint"] = "Push new chronicle events to the web interface in real-time (home page Live Chronicle section).",
                ["mcm_show_hud_stats_hint"] = "Display the player HUD bar in the web interface showing gold, influence, health, troops, and other live stats.",
                ["mcm_show_intro_screen_hint"] = "Show the animated intro screen with Viking artwork when the web encyclopedia first loads.",
                ["mcm_show_ember_particles_hint"] = "Display ambient floating ember particles in the web interface for atmosphere. Disable for better performance.",
                ["mcm_show_gold_spark_trail_hint"] = "Display the gold spark trail effect that follows the mouse cursor. Disable for better performance.",
                ["mcm_enable_sound_effects_hint"] = "Play subtle UI sound effects (hover, click, navigation) in the web interface.",
                ["mcm_enable_scroll_animations_hint"] = "Cards and sections animate into view as you scroll. Disable for instant rendering.",
                ["mcm_cards_per_page_hint"] = "Number of cards shown per page in list views (Heroes, Clans, Settlements, Kingdoms). Higher values may impact performance.",
                ["mcm_open_web_encyclopedia_hint"] = "Open the web encyclopedia in your default browser.",

