                ["mcm_max_name_length_hint"] = "Максимум символов при редактировании имени/титула через Ctrl+N. Короткие лимиты предотвращают переполнение UI.",
                ["mcm_enable_clan_editing_hint"] = "Разрешает редактировать описания на страницах кланов.",
