                ["mcm_enable_banner_flag_editing_hint"] = "Разрешает редактировать знамёна/флаги по Ctrl+B. Вставьте код знамени, чтобы сменить его у Героев, Кланов, Королевств или Поселений.",
                ["mcm_enable_culture_editing_hint"] = "Разрешает менять культуру героя по Ctrl+U. Можно выбрать существующую культуру или создать свою.",
                ["mcm_enable_occupation_editing_hint"] = "Разрешает менять занятие героя по Ctrl+O. Выбор из доступных занятий (Лорд, Странник, Торговец и т. д.).",
                ["mcm_enable_tag_editing_hint"] = "Разрешает добавлять пользовательские теги (союзник, враг, цель) к любой записи по Ctrl+G. Теги показываются на странице и включаются в экспорты.",
                ["mcm_tag_font_scale_hint"] = "Масштабирует размер шрифта тегов на страницах энциклопедии в процентах. 100 = нормально, 130 = по умолчанию (1.3×), 200 = двойной размер.",
                ["mcm_enable_auto_tags_hint"] = "Автоматически создаёт теги для героев на основе состояния игры (отношения, размер отряда, богатство клана). Авто-теги отображаются с префиксом «Auto:» и пересчитываются ежедневно.",
                ["mcm_auto_tag_enemy_relation_hint"] = "Герои с отношением на уровне или ниже этого порога получают тег «Auto: Enemy». По умолчанию: −30.",
                ["mcm_auto_tag_friend_relation_hint"] = "Герои с отношением на уровне или выше этого порога получают тег «Auto: Friend». По умолчанию: 30.",
                ["mcm_auto_tag_dangerous_party_size_hint"] = "Герои, ведущие отряды такого или большего размера, получают тег «Auto: Dangerous». По умолчанию: 200.",
                ["mcm_enable_journal_hint"] = "Разрешает добавлять заметки хроники (дневник кампании) к любой записи по Ctrl+J. Отображаются в секции «Журнал» на странице.",
                ["mcm_enable_auto_chronicle_hint"] = "Автоматически фиксирует игровые события (битвы, дипломатия, турниры, пленения и т. д.) как заметки хроники в связанных записях.",
                ["mcm_enable_global_chronicle_panel_hint"] = "Показывает на карте кампании кнопку «Заметки хроники», открывающую панель со всеми мировыми событиями (объявления войн, мирные договоры, политические изменения).",
                ["mcm_enable_relation_notes_hint"] = "Разрешает писать личные заметки об отношениях героев по Ctrl+F. Заметки появляются в секции Друзья/Враги на странице героя.",
                ["mcm_enable_timeline_hint"] = "Показывает на странице героя секцию «Хронология» с личной биографией в хронологическом порядке (битвы, пленения, семья, ручные заметки).",
                ["mcm_timeline_page_size_hint"] = "Количество записей хронологии на страницу. Меньшие значения повышают производительность. По умолчанию: 25.",
                ["mcm_enable_lore_section_hint"] = "Показывает сворачиваемую секцию «Лор» на страницах героев (История, Характер, Цели, Отношения, Слухи). Отключить — скрыть секцию полностью.",
                ["mcm_enable_info_stats_hint"] = "Показывает панель статистики «Инфо» на страницах (Герой: Культура, Войска, Убийства, Ранг и т. д. | Клан: Слава, Войска и т. д. | Королевство: Кланы, Войны и т. д. | Поселение: Процветание, Лояльность и т. д.).",
                ["mcm_show_edit_popup_portrait_hint"] = "Показывает портрет героя или герб клана/королевства в заголовке окна редактирования. Отключить — для более простого вида окна.",
                ["mcm_journal_page_size_hint"] = "Количество записей журнала/хроники на страницу в энциклопедии. По умолчанию: 10.",
                ["mcm_chronicle_panel_page_size_hint"] = "Количество записей на страницу в глобальной панели хроники на карте. По умолчанию: 22.",
                ["mcm_show_journal_hint_hint"] = "Показывает «J Журнал» в подсказке горячих клавиш на страницах энциклопедии.",
                ["mcm_show_relation_note_hint_hint"] = "Показывает «F Заметка о друге» в подсказке горячих клавиш на страницах героев.",
                ["mcm_prevent_kingdom_color_overwrites_hint"] = "В версии 1.3.13 игра часто принудительно возвращает знамёна к цветам культуры по умолчанию. Включите, чтобы периодически заново применять ваши знамёна, когда игра их переписывает.",
                ["mcm_create_custom_banner_hint"] = "Открывает bannerlord.party/banner в браузере, где можно создать своё знамя и скопировать код. Затем используйте Ctrl+B в энциклопедии, чтобы вставить его.",
                ["mcm_manage_custom_cultures_hint"] = "Просмотр и удаление пользовательских назначений культур. Показывает список героев с настраиваемыми культурами — нажмите, чтобы удалить и вернуть оригинал.",
                ["mcm_manage_custom_occupations_hint"] = "Просмотр и удаление пользовательских назначений занятий. Показывает список героев с настраиваемыми занятиями — нажмите, чтобы удалить и вернуть оригинал.",
                ["mcm_manage_tags_hint"] = "Просмотр, переименование и удаление тегов для всех записей энциклопедии. Позволяет массовое управление тегами из меню настроек.",
                ["mcm_filter_by_tag_hint"] = "Поиск всех записей энциклопедии с заданным тегом. Показывает подходящих героев, кланы, королевства и поселения.",
                ["mcm_manage_tag_presets_hint"] = "Сохранение и загрузка пресетов тегов (шаблонов). Пресет — это именованный набор тегов, быстро применяемый к любой записи.",
                ["mcm_manage_tag_categories_hint"] = "Создание и управление пользовательскими категориями тегов. Категории группируют теги в быстром меню и отображении.",
                ["mcm_export_all_to_json_hint"] = "Экспортирует все пользовательские данные в JSON-файл v10, который можно передать или импортировать в другую кампанию.",
                ["mcm_import_all_from_json_hint"] = "Импортирует все данные из JSON-файла на диске и объединяет с текущей кампанией. Существующие записи перезаписываются.",
