                ["mcm_reset_all_descriptions_hint"] = "Удаляет ВСЕ пользовательские описания из текущей кампании. Отменить нельзя!",
                ["mcm_initial_key_poll_delay_ms_hint"] = "Задержка в миллисекундах перед запуском опрашивателя Ctrl+E после открытия страницы энциклопедии. Предотвращает случайные срабатывания.",
                ["mcm_key_poll_interval_ms_hint"] = "Как часто (в миллисекундах) мод проверяет нажатие Ctrl+E. Меньше = отзывчивее, больше = меньше нагрузки на ЦП.",
                ["mcm_max_description_length_hint"] = "Максимум символов для основного поля «Описание». Установите 0 для неограниченного.",
                ["mcm_max_narrative_field_length_hint"] = "Максимум символов для полей повествования (Биография, Слухи/Тайны). Установите 0 для неограниченного.",
                ["mcm_max_stats_field_length_hint"] = "Максимум символов для коротких полей статистики (Характер, Цели, Отношения). Установите 0 для неограниченного.",
                ["mcm_language_hint"] = "Язык всплывающих окон, сообщений и строк времени выполнения. Применяется вживую — перезапуск не нужен. Файлы языков: Documents/Mount and Blade II Bannerlord/Configs/ModSettings/Global/EditableEncyclopedia/Languages/.",
                ["mcm_debug_mode_hint"] = "Включает подробное ведение журнала в файл debug.log (в папке настроек EditableEncyclopedia). Не показывает сообщения на экране, если также не включён «Отладка на экране».",
                ["mcm_show_debug_on_screen_hint"] = "При включённом режиме отладки также выводит отладочные сообщения жёлтым текстом в игре. Внимание: очень подробно, может загромождать экран, особенно на страницах энциклопедии.",
                ["mcm_enable_web_extension_eewebextension_hint"] = "Включает мод EE Web Extension. Когда включён и модуль EEWebExtension установлен, локальный веб-сервер работает по http://127.0.0.1:8080/ для просмотра и редактирования энциклопедии из браузера. Требуется перезапуск игры.",
                ["mcm_web_extension_status_hint"] = "Показывает, загружен и запущен ли сейчас модуль EE Web Extension.",
                ["mcm_web_server_port_hint"] = "Номер порта веб-сервера. По умолчанию 8080 (http://127.0.0.1:8080). Измените, если порт 8080 занят другим приложением. Требуется перезапуск.",
                ["mcm_auto_open_browser_hint"] = "Автоматически открывает веб-энциклопедию в браузере по умолчанию при загрузке кампании.",
                ["mcm_allow_external_access_hint"] = "Разрешает подключения с других устройств в локальной сети (телефон, планшет). OFF — доступ только с этого ПК. ON — любое устройство сети может подключиться по IP ПК. Требуется перезапуск.",
                ["mcm_enable_editing_from_web_hint"] = "Разрешает редактирование записей (описаний, имён, тегов и т. д.) через веб-интерфейс. OFF — только чтение.",
                ["mcm_enable_portrait_extraction_hint"] = "Разрешает веб-расширению извлекать портреты героев из игры для отображения в веб-интерфейсе.",
                ["mcm_live_sync_interval_seconds_hint"] = "Как часто веб-вид деталей обновляется живыми данными игры. Меньше = отзывчивее, но больше нагрузки. По умолчанию 8 секунд.",
                ["mcm_live_sync_on_detail_views_hint"] = "Автоматически обновляет детальные виды (Герой, Клан, Поселение, Королевство) живыми данными игры. При активности показывается значок LIVE.",
                ["mcm_live_chronicle_updates_hint"] = "Отправляет новые события хроники в веб-интерфейс в реальном времени (секция «Живая хроника» на главной).",
                ["mcm_show_hud_stats_hint"] = "Показывает HUD-панель игрока в веб-интерфейсе (золото, влияние, здоровье, войска и другие живые статы).",
                ["mcm_show_intro_screen_hint"] = "Показывает анимированный вступительный экран с викингской графикой при первой загрузке веб-энциклопедии.",
                ["mcm_show_ember_particles_hint"] = "Показывает плавающие частицы углей в веб-интерфейсе для атмосферы. Отключите для лучшей производительности.",
                ["mcm_show_gold_spark_trail_hint"] = "Показывает золотой след искр, следующий за курсором. Отключите для лучшей производительности.",
                ["mcm_enable_sound_effects_hint"] = "Воспроизводит тонкие звуковые эффекты UI (наведение, щелчок, навигация) в веб-интерфейсе.",
                ["mcm_enable_scroll_animations_hint"] = "Карточки и секции появляются с анимацией при прокрутке. Отключите для мгновенного отображения.",
                ["mcm_cards_per_page_hint"] = "Количество карточек на страницу в списках (Герои, Кланы, Поселения, Королевства). Большие значения могут влиять на производительность.",
                ["mcm_open_web_encyclopedia_hint"] = "Открывает веб-энциклопедию в браузере по умолчанию.",
            };
        }

