                ["mcm_web_server_port_hint"] = "Web サーバーのポート番号。デフォルト 8080 (http://127.0.0.1:8080)。別アプリが 8080 を使用する場合は変更。再起動が必要。",
                ["mcm_auto_open_browser_hint"] = "キャンペーンロード時に既定のブラウザで Web 百科を自動的に開きます。",
                ["mcm_allow_external_access_hint"] = "ローカルネットワーク上の他の機器（スマホ、タブレット）からの接続を許可します。OFF = この PC のみアクセス可能。ON = ネットワーク上の任意の機器が PC の IP アドレス経由で接続可能。再起動が必要。",
                ["mcm_enable_editing_from_web_hint"] = "Web インターフェースからの項目編集（説明、名前、タグなど）を許可します。OFF では読み取り専用。",
                ["mcm_enable_portrait_extraction_hint"] = "Web 拡張がゲームから英雄の肖像を抽出し Web インターフェースに表示するのを許可します。",
                ["mcm_live_sync_interval_seconds_hint"] = "Web 詳細ビューがライブゲームデータで自動更新される頻度。低いほど反応的だが CPU 負荷増。デフォルト 8 秒。",
                ["mcm_live_sync_on_detail_views_hint"] = "詳細ビュー（英雄、氏族、居住地、王国）をライブゲームデータで自動更新します。アクティブ時に LIVE バッジを表示。",
                ["mcm_live_chronicle_updates_hint"] = "新しい年代記イベントをリアルタイムで Web インターフェースにプッシュします（ホームページのライブ年代記セクション）。",
                ["mcm_show_hud_stats_hint"] = "Web インターフェースにプレイヤー HUD バーを表示し、金、影響力、体力、兵士その他のライブ統計を表示します。",
                ["mcm_show_intro_screen_hint"] = "Web 百科の初回読み込み時にバイキングのアートワークによるアニメーション付きイントロ画面を表示します。",
                ["mcm_show_ember_particles_hint"] = "雰囲気のために Web インターフェースに浮遊する残り火パーティクルを表示します。無効化でパフォーマンス向上。",
                ["mcm_show_gold_spark_trail_hint"] = "マウスカーソルを追う金色の火花の軌跡を表示します。無効化でパフォーマンス向上。",
                ["mcm_enable_sound_effects_hint"] = "Web インターフェースで繊細な UI 効果音（ホバー、クリック、ナビゲーション）を再生します。",
                ["mcm_enable_scroll_animations_hint"] = "スクロール時にカードやセクションがアニメーションで表示されます。無効化で即時レンダリング。",
                ["mcm_cards_per_page_hint"] = "リストビュー（英雄、氏族、居住地、王国）の 1 ページあたりのカード数。高い値はパフォーマンスに影響する可能性があります。",
                ["mcm_open_web_encyclopedia_hint"] = "既定のブラウザで Web 百科を開きます。",
            };
        }

