                ["mcm_key_poll_interval_ms_hint"] = "Jak często (w ms) mod sprawdza naciśnięcie Ctrl+E. Niższe = większa responsywność, wyższe = mniejsze użycie CPU.",
                ["mcm_max_description_length_hint"] = "Maksymalna liczba znaków głównego pola Opisu. Ustaw 0, aby bez limitu.",
