                ["mcm_language_hint"] = "Język wyskakujących okienek, komunikatów i ciągów runtime. Stosuje się na żywo — bez restartu. Pliki językowe: Documents/Mount and Blade II Bannerlord/Configs/ModSettings/Global/EditableEncyclopedia/Languages/.",
                ["mcm_debug_mode_hint"] = "Włącza szczegółowe logowanie do pliku debug.log (w folderze konfiguracji EditableEncyclopedia). Nie wyświetla komunikatów na ekranie, chyba że włączone jest również „Debug na ekranie”.",
                ["mcm_show_debug_on_screen_hint"] = "Gdy tryb debugowania jest włączony, wyświetla komunikaty debugowania również jako żółty tekst w grze. Uwaga: bardzo obszerne, może zaśmiecać ekran, zwłaszcza na stronach encyklopedii.",
                ["mcm_enable_web_extension_eewebextension_hint"] = "Włącza moda EE Web Extension. Gdy włączony i moduł EEWebExtension jest zainstalowany, lokalny serwer WWW działa pod http://127.0.0.1:8080/ pozwalając przeglądać i edytować encyklopedię z przeglądarki. Wymaga restartu gry.",
                ["mcm_web_extension_status_hint"] = "Pokazuje, czy moduł EE Web Extension jest obecnie załadowany i działa.",
                ["mcm_web_server_port_hint"] = "Numer portu serwera WWW. Domyślnie 8080 (http://127.0.0.1:8080). Zmień, jeśli inna aplikacja używa portu 8080. Wymaga restartu.",
                ["mcm_auto_open_browser_hint"] = "Automatycznie otwiera encyklopedię WWW w domyślnej przeglądarce po wczytaniu kampanii.",
                ["mcm_allow_external_access_hint"] = "Zezwala na połączenia z innych urządzeń w sieci lokalnej (telefon, tablet). OFF = tylko ten PC ma dostęp. ON = dowolne urządzenie w sieci może się łączyć przez IP PC. Wymaga restartu.",
                ["mcm_enable_editing_from_web_hint"] = "Zezwala na edycję wpisów (opisów, nazw, tagów itp.) z interfejsu WWW. OFF = tylko do odczytu.",
                ["mcm_enable_portrait_extraction_hint"] = "Zezwala rozszerzeniu WWW na ekstrahowanie portretów bohaterów z gry do wyświetlania w interfejsie.",
                ["mcm_live_sync_interval_seconds_hint"] = "Jak często widoki szczegółów WWW automatycznie odświeżają się danymi na żywo z gry. Niższe = większa responsywność, ale większe użycie CPU. Domyślnie 8 sekund.",
                ["mcm_live_sync_on_detail_views_hint"] = "Automatycznie odświeża widoki szczegółów (Bohater, Klan, Osada, Królestwo) danymi na żywo. Pokazuje plakietkę LIVE, gdy aktywne.",
                ["mcm_live_chronicle_updates_hint"] = "Wysyła nowe wydarzenia kroniki do interfejsu WWW w czasie rzeczywistym (sekcja Kroniki Live na stronie głównej).",
                ["mcm_show_hud_stats_hint"] = "Wyświetla pasek HUD gracza w interfejsie WWW, pokazując złoto, wpływy, zdrowie, wojsko i inne statystyki na żywo.",
                ["mcm_show_intro_screen_hint"] = "Wyświetla animowany ekran intro z wikingską grafiką przy pierwszym uruchomieniu encyklopedii WWW.",
                ["mcm_show_ember_particles_hint"] = "Wyświetla unoszące się cząstki żaru w interfejsie WWW dla atmosfery. Wyłącz dla lepszej wydajności.",
                ["mcm_show_gold_spark_trail_hint"] = "Wyświetla efekt złotego śladu iskier podążający za kursorem. Wyłącz dla lepszej wydajności.",
                ["mcm_enable_sound_effects_hint"] = "Odtwarza subtelne efekty dźwiękowe UI (najechanie, kliknięcie, nawigacja) w interfejsie WWW.",
                ["mcm_enable_scroll_animations_hint"] = "Karty i sekcje pojawiają się z animacją podczas przewijania. Wyłącz dla natychmiastowego renderowania.",
                ["mcm_cards_per_page_hint"] = "Liczba kart na stronę w widokach listy (Bohaterowie, Klany, Osady, Królestwa). Wyższe wartości mogą wpływać na wydajność.",
                ["mcm_open_web_encyclopedia_hint"] = "Otwiera encyklopedię WWW w domyślnej przeglądarce.",
