                // Підказки властивостей MCM (tooltips) — українська
                ["mcm_author_hint"] = "Автор цього мода.",
                ["mcm_version_hint"] = "Поточна версія Editable Encyclopedia.",
                ["mcm_join_discord_hint"] = "Клацніть, щоб відкрити посилання-запрошення Discord (discord.com/users/404393620897136640) у браузері.",
                ["mcm_encyclopedia_edit_statistics_hint"] = "Показує підсумок усіх власних правок у поточній кампанії: описи, імена, титули, прапори, культури, заняття, поля лору, теги, записи журналу та нотатки стосунків.",
                ["mcm_open_config_folder_hint"] = "Відкриває теку налаштувань EditableEncyclopedia, де зберігаються JSON-файли MCM.",
                ["mcm_show_edit_hint_hint"] = "Додає «[Ctrl+E — редагувати опис]» до тексту сторінок енциклопедії.",
                ["mcm_show_name_edit_hint_hint"] = "Показує підказку «[Ctrl+N — редагувати ім'я]» на сторінках героїв.",
                ["mcm_show_banner_edit_hint_hint"] = "Показує підказку «[Ctrl+B — редагувати прапор]» на сторінках енциклопедії.",
                ["mcm_show_culture_edit_hint_hint"] = "Показує підказку «[Ctrl+U — редагувати культуру]» на сторінках героїв.",
                ["mcm_show_occupation_edit_hint_hint"] = "Показує підказку «[Ctrl+O — редагувати заняття]» на сторінках героїв.",
                ["mcm_show_tag_edit_hint_hint"] = "Показує підказку «[G теги]» на сторінках енциклопедії.",
                ["mcm_show_confirmation_messages_hint"] = "Показує зелене повідомлення під час збереження опису.",
                ["mcm_show_edited_indicator_hint"] = "Додає «[Редаговано]» на початку власних описів для легшої ідентифікації.",
                ["mcm_show_edit_timestamp_hint"] = "Показує внутрішньоігрову дату останнього редагування опису (напр.: «Редаговано: 15-й день весни, 1084»).",
                ["mcm_auto_export_on_save_hint"] = "Автоматично експортує всі дані у спільний JSON-файл при кожному збереженні. Підтримує файл експорту завжди актуальним.",
                ["mcm_auto_import_on_load_hint"] = "Автоматично імпортує всі дані зі спільного JSON-файлу під час завантаження. Корисно для синхронізації даних між кампаніями.",
                ["mcm_enable_hero_editing_hint"] = "Дозволяє редагувати описи на сторінках Героїв.",
                ["mcm_enable_name_editing_ctrl_n_hint"] = "Дозволяє редагувати імена через Ctrl+N. Працює на сторінках Героя (ім'я + титул), Клану, Королівства та Поселення.",
                ["mcm_max_name_length_hint"] = "Максимум символів при редагуванні імен/титулів через Ctrl+N. Коротші ліміти запобігають переповненню UI.",
                ["mcm_enable_clan_editing_hint"] = "Дозволяє редагувати описи на сторінках Кланів.",
                ["mcm_enable_kingdom_editing_hint"] = "Дозволяє редагувати описи на сторінках Королівств/Фракцій.",
                ["mcm_enable_settlement_editing_hint"] = "Дозволяє редагувати описи на сторінках Поселень.",
                ["mcm_enable_banner_flag_editing_hint"] = "Дозволяє редагувати прапори/стяги через Ctrl+B. Вставте код прапора, щоб змінити його у Героїв, Кланів, Королівств або Поселень.",
                ["mcm_enable_culture_editing_hint"] = "Дозволяє змінювати культуру героя через Ctrl+U. Оберіть серед наявних культур або створіть власну.",
                ["mcm_enable_occupation_editing_hint"] = "Дозволяє змінювати заняття героя через Ctrl+O. Оберіть серед доступних занять (Лорд, Мандрівник, Купець тощо).",
                ["mcm_enable_tag_editing_hint"] = "Дозволяє додавати користувацькі теги (союзник, ворог, ціль) до будь-якого запису через Ctrl+G. Теги показуються на сторінці та в експортах.",
                ["mcm_tag_font_scale_hint"] = "Масштабує розмір шрифту тегів у відсотках. 100 = звичайний, 130 = за замовчуванням (1.3×), 200 = подвійний.",
                ["mcm_enable_auto_tags_hint"] = "Автоматично створює теги для героїв на основі стану гри (стосунки, розмір загону, багатство клану). Автотеги мають префікс «Auto:» і перераховуються щодня.",
                ["mcm_auto_tag_enemy_relation_hint"] = "Герої зі стосунками на цьому порозі чи нижче отримують тег «Auto: Enemy». За замовчуванням: -30.",
                ["mcm_auto_tag_friend_relation_hint"] = "Герої зі стосунками на цьому порозі чи вище отримують тег «Auto: Friend». За замовчуванням: 30.",
                ["mcm_auto_tag_dangerous_party_size_hint"] = "Герої, що очолюють загони такого розміру або більше, отримують тег «Auto: Dangerous». За замовчуванням: 200.",
                ["mcm_enable_journal_hint"] = "Дозволяє додавати нотатки хроніки (щоденник кампанії) до будь-якого запису через Ctrl+J. Відображаються у секції «Журнал» на сторінці.",
                ["mcm_enable_auto_chronicle_hint"] = "Автоматично записує ігрові події (битви, дипломатія, турніри, полонення тощо) як нотатки хроніки у відповідних записах.",
                ["mcm_enable_global_chronicle_panel_hint"] = "Показує кнопку «Нотатки хроніки» на мапі кампанії, що відкриває панель з усіма світовими подіями.",
                ["mcm_enable_relation_notes_hint"] = "Дозволяє писати особисті нотатки про стосунки героїв через Ctrl+F. З'являються у секції Друзі/Вороги на сторінках героїв.",
                ["mcm_enable_timeline_hint"] = "Показує секцію «Хронологія» на сторінках героїв з хронологічною особистою біографією (битви, полонення, сім'я, ручні нотатки).",
                ["mcm_timeline_page_size_hint"] = "Кількість записів хронології на сторінку. Нижчі значення покращують продуктивність. За замовчуванням: 25.",
                ["mcm_enable_lore_section_hint"] = "Показує згортувану секцію «Лор» на сторінках героїв (Історія, Характер, Цілі, Стосунки, Чутки). Вимкніть, щоб приховати.",
                ["mcm_enable_info_stats_hint"] = "Показує панель статистики «Інфо» на сторінках (Герой, Клан, Королівство, Поселення).",
                ["mcm_show_edit_popup_portrait_hint"] = "Показує портрет героя або емблему клану/королівства у заголовку вікна редагування.",
                ["mcm_journal_page_size_hint"] = "Кількість записів журналу/хроніки на сторінку в енциклопедії. За замовчуванням: 10.",
                ["mcm_chronicle_panel_page_size_hint"] = "Кількість записів на сторінку у Глобальній панелі хроніки на мапі. За замовчуванням: 22.",
                ["mcm_show_journal_hint_hint"] = "Показує «J Журнал» у підказці гарячих клавіш на сторінках енциклопедії.",
                ["mcm_show_relation_note_hint_hint"] = "Показує «F Нотатка про друга» у підказці гарячих клавіш на сторінках героїв.",
                ["mcm_prevent_kingdom_color_overwrites_hint"] = "У 1.3.13 ігрова логіка королівств часто примусово повертає прапори до кольорів культури за замовчуванням. Увімкніть, щоб періодично знову застосовувати ваші прапори, коли гра їх перезаписує.",
                ["mcm_create_custom_banner_hint"] = "Відкриває bannerlord.party/banner у браузері, де можна створити власний прапор і скопіювати код. Потім використайте Ctrl+B в енциклопедії, щоб вставити його.",
                ["mcm_manage_custom_cultures_hint"] = "Переглянути та видалити користувацькі призначення культур. Показує список героїв із власними культурами — клацніть, щоб видалити та відновити оригінал.",
                ["mcm_manage_custom_occupations_hint"] = "Переглянути та видалити користувацькі призначення занять. Показує список героїв із власними заняттями — клацніть, щоб видалити та відновити оригінал.",
                ["mcm_manage_tags_hint"] = "Переглядати, перейменовувати та видаляти теги по всіх записах енциклопедії. Дозволяє масове керування тегами з меню налаштувань.",
                ["mcm_filter_by_tag_hint"] = "Шукає всі записи енциклопедії з певним тегом. Показує відповідних героїв, клани, королівства та поселення.",
                ["mcm_manage_tag_presets_hint"] = "Зберігає та завантажує передналаштування тегів (шаблони). Передналаштування — це іменований набір тегів, який можна швидко застосувати до будь-якого запису.",
                ["mcm_manage_tag_categories_hint"] = "Створює та керує власними категоріями тегів. Категорії групують теги у Швидкому меню тегів та відображенні.",
                ["mcm_export_all_to_json_hint"] = "Експортує всі власні дані у файл JSON v10, яким можна поділитися або імпортувати в іншу кампанію.",
                ["mcm_import_all_from_json_hint"] = "Імпортує всі дані з JSON-файлу на диску та об'єднує з поточною кампанією. Наявні записи перезаписуються.",
                ["mcm_export_heroes_only_hint"] = "Експортує лише описи Героїв у спільний JSON-файл.",
                ["mcm_export_clans_only_hint"] = "Експортує лише описи Кланів у спільний JSON-файл.",
                ["mcm_export_kingdoms_only_hint"] = "Експортує лише описи Королівств у спільний JSON-файл.",
                ["mcm_export_settlements_only_hint"] = "Експортує лише описи Поселень у спільний JSON-файл.",
                ["mcm_export_banners_only_hint"] = "Експортує лише коди власних прапорів у спільний JSON-файл.",
                ["mcm_import_banners_only_hint"] = "Імпортує лише коди власних прапорів зі спільного JSON-файлу у поточну кампанію.",
                ["mcm_reset_all_descriptions_hint"] = "Видаляє ВСІ власні описи з поточної кампанії. Скасувати не можна!",
                ["mcm_initial_key_poll_delay_ms_hint"] = "Затримка у мс перед запуском опитувача Ctrl+E після відкриття сторінки енциклопедії. Запобігає випадковим спрацюванням.",
                ["mcm_key_poll_interval_ms_hint"] = "Як часто (у мс) мод перевіряє натискання Ctrl+E. Нижче = чутливіше, вище = менше CPU.",
                ["mcm_max_description_length_hint"] = "Максимум символів основного поля Опису. Встановіть 0 для необмеженого.",
                ["mcm_max_narrative_field_length_hint"] = "Максимум символів для оповідних полів (Біографія, Чутки/Таємниці). Встановіть 0 для необмеженого.",
                ["mcm_max_stats_field_length_hint"] = "Максимум символів для коротких полів статистики (Характер, Цілі, Стосунки). Встановіть 0 для необмеженого.",
                ["mcm_language_hint"] = "Мова спливаючих вікон, повідомлень та рядків часу виконання. Застосовується наживо — без перезапуску. Файли: Documents/Mount and Blade II Bannerlord/Configs/ModSettings/Global/EditableEncyclopedia/Languages/.",
                ["mcm_debug_mode_hint"] = "Вмикає докладне ведення журналу у файл debug.log (у теці налаштувань EditableEncyclopedia). Не показує повідомлення на екрані, якщо не увімкнено також «Налагодження на екрані».",
                ["mcm_show_debug_on_screen_hint"] = "Коли режим налагодження увімкнено, також показує повідомлення налагодження жовтим текстом у грі. Увага: дуже багатослівно, може захаращувати екран.",
                ["mcm_enable_web_extension_eewebextension_hint"] = "Вмикає мод EE Web Extension. Коли увімкнено та модуль EEWebExtension встановлено, локальний веб-сервер працює за http://127.0.0.1:8080/ для перегляду та редагування енциклопедії з браузера. Потрібен перезапуск гри.",
                ["mcm_web_extension_status_hint"] = "Показує, чи наразі завантажено та запущено модуль EE Web Extension.",
                ["mcm_web_server_port_hint"] = "Номер порту веб-сервера. За замовчуванням 8080 (http://127.0.0.1:8080). Змініть, якщо інший застосунок використовує 8080. Потрібен перезапуск.",
                ["mcm_auto_open_browser_hint"] = "Автоматично відкриває веб-енциклопедію у браузері за замовчуванням при завантаженні кампанії.",
                ["mcm_allow_external_access_hint"] = "Дозволяє підключення з інших пристроїв локальної мережі (телефон, планшет). OFF = лише цей ПК має доступ. ON = будь-який пристрій мережі може підключитися за IP ПК. Потрібен перезапуск.",
                ["mcm_enable_editing_from_web_hint"] = "Дозволяє редагувати записи (описи, імена, теги тощо) з веб-інтерфейсу. OFF = лише перегляд.",
                ["mcm_enable_portrait_extraction_hint"] = "Дозволяє веб-розширенню витягувати портрети героїв з гри для відображення у веб-інтерфейсі.",
                ["mcm_live_sync_interval_seconds_hint"] = "Як часто веб-перегляди деталей авто-оновлюються живими ігровими даними. Нижче = чутливіше, але більше CPU. За замовчуванням 8 секунд.",
