        // ── JSON Helpers ──────────────────────────────────────

        private static string EscapeJson(string s)
        {
            if (string.IsNullOrEmpty(s)) return "";
            var sb = new StringBuilder(s.Length);
            foreach (char c in s)
            {
                switch (c)
                {
                    case '\\': sb.Append("\\\\"); break;
                    case '"': sb.Append("\\\""); break;
                    case '\n': sb.Append("\\n"); break;
                    case '\r': sb.Append("\\r"); break;
                    case '\t': sb.Append("\\t"); break;
                    default: sb.Append(c); break;
                }
            }
            return sb.ToString();
        }

        private static Dictionary<string, string> ParseSimpleJson(string json)
        {
            // Reuse SharedFileExporter's parsing approach for flat key-value JSON
            var result = new Dictionary<string, string>();
            int pos = json.IndexOf('{');
            if (pos == -1) return result;
            pos++;

            while (pos < json.Length)
            {
                while (pos < json.Length && (char.IsWhiteSpace(json[pos]) || json[pos] == ','))
                    pos++;
                if (pos >= json.Length || json[pos] == '}') break;
                if (json[pos] != '"') break;

                // Parse key
                pos++;
                int keyStart = pos;
                while (pos < json.Length && json[pos] != '"')
                {
                    if (json[pos] == '\\') pos++;
                    pos++;
                }
                string key = UnescapeJson(json.Substring(keyStart, pos - keyStart));
                pos++; // skip closing quote

                // Skip colon
                while (pos < json.Length && (char.IsWhiteSpace(json[pos]) || json[pos] == ':'))
                    pos++;

                if (pos >= json.Length || json[pos] != '"') break;

                // Parse value
                pos++;
                int valStart = pos;
                while (pos < json.Length && json[pos] != '"')
                {
                    if (json[pos] == '\\') pos++;
                    pos++;
                }
                string value = UnescapeJson(json.Substring(valStart, pos - valStart));
                pos++; // skip closing quote

                result[key] = value;
            }

            return result;
        }

        private static string UnescapeJson(string s)
        {
            if (string.IsNullOrEmpty(s) || !s.Contains("\\")) return s;
            var sb = new StringBuilder(s.Length);
            for (int i = 0; i < s.Length; i++)
            {
                if (s[i] == '\\' && i + 1 < s.Length)
                {
                    switch (s[i + 1])
                    {
                        case '\\': sb.Append('\\'); i++; break;
                        case '"': sb.Append('"'); i++; break;
                        case 'n': sb.Append('\n'); i++; break;
                        case 'r': sb.Append('\r'); i++; break;
                        case 't': sb.Append('\t'); i++; break;
                        default: sb.Append('\\'); break;
                    }
                }
                else
                {
                    sb.Append(s[i]);
                }
            }
            return sb.ToString();
        }
    }
}
